// 프로젝트 생성/편집 모달
import { useState, useEffect, useRef } from 'react';
import type { Project, ProjectTask } from '../../types/work';
import { useDraggable } from '../../hooks/useDraggable';
import './ProjectModal.css';

interface ProjectModalProps {
  project: Project | null; // null이면 새 프로젝트 생성
  isOpen: boolean;
  tasks: ProjectTask[]; // 해당 프로젝트의 태스크 목록
  onClose: () => void;
  onSave: (project: Partial<Project>) => void;
  onDelete?: (projectId: string) => void;
  onTaskClick?: (task: ProjectTask) => void;
  onAddTask?: (title: string) => void;
}

// 저채도 파스텔 색상 (15개)
const COLORS = [
  '#a5b4fc', // 연보라 (indigo)
  '#93c5fd', // 연파랑 (blue)
  '#7dd3fc', // 연하늘 (sky)
  '#67e8f9', // 연청록 (cyan)
  '#5eead4', // 연민트 (teal)
  '#86efac', // 연초록 (green)
  '#a3e635', // 연라임 (lime)
  '#fde68a', // 연노랑 (yellow)
  '#fcd34d', // 연금색 (amber)
  '#fed7aa', // 연주황 (orange)
  '#fca5a5', // 연빨강 (red)
  '#fda4af', // 연장미 (rose)
  '#f9a8d4', // 연분홍 (pink)
  '#c4b5fd', // 연보라 (purple)
  '#cbd5e1', // 연회색 (slate)
];

export default function ProjectModal({
  project,
  isOpen,
  tasks,
  onClose,
  onSave,
  onDelete,
  onTaskClick,
  onAddTask,
}: ProjectModalProps) {
  const [title, setTitle] = useState('');
  const [color, setColor] = useState(COLORS[0]);
  const [description, setDescription] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [isAllDay, setIsAllDay] = useState(true);
  const [newTaskTitle, setNewTaskTitle] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [dateError, setDateError] = useState('');
  
  const titleRef = useRef<HTMLInputElement>(null);
  const { position, isDragging, handleMouseDown, resetPosition } = useDraggable();

  const isNew = !project;

  // 날짜 유효성 검사
  const validateDates = (): boolean => {
    if (startDate && endDate) {
      const startDT = new Date(startDate);
      const endDT = new Date(endDate);
      if (endDT < startDT) {
        setDateError('종료일은 시작일보다 이후여야 합니다');
        return false;
      }
    }
    setDateError('');
    return true;
  };

  useEffect(() => {
    if (isOpen) {
      if (project) {
        setTitle(project.title);
        setColor(project.color);
        setDescription(project.description || '');
        setStartDate(project.start_at ? project.start_at.split('T')[0] : '');
        setEndDate(project.end_at ? project.end_at.split('T')[0] : '');
        setDueDate(project.due_at ? project.due_at.split('T')[0] : '');
        setIsAllDay(project.is_all_day);
      } else {
        // 새 프로젝트
        setTitle('');
        setColor(COLORS[0]);
        setDescription('');
        setStartDate('');
        setEndDate('');
        setDueDate('');
        setIsAllDay(true);
        setNewTaskTitle('');
      }
      setDateError('');
      resetPosition(); // 모달 열 때 위치 리셋
      setTimeout(() => titleRef.current?.focus(), 100);
    }
  }, [isOpen, project, resetPosition]);

  const handleSave = async () => {
    if (!title.trim() || isSaving) return;
    if (!validateDates()) return;
    
    setIsSaving(true);
    try {
      await onSave({
        ...project,
        title: title.trim(),
        color,
        description: description.trim(),
        start_at: startDate ? `${startDate}T00:00:00` : null,
        end_at: endDate ? `${endDate}T23:59:59` : null,
        due_at: dueDate ? `${dueDate}T23:59:59` : null,
        is_all_day: isAllDay,
      });
      onClose();
    } catch (error) {
      console.error('Failed to save project:', error);
      alert('저장에 실패했습니다.');
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = () => {
    if (!project || !onDelete) return;
    if (confirm('정말로 이 프로젝트를 삭제하시겠습니까?\n소속된 모든 Task와 To do도 함께 삭제됩니다.')) {
      onDelete(project.id);
      onClose();
    }
  };

  const handleAddTask = () => {
    if (!newTaskTitle.trim() || !onAddTask) return;
    onAddTask(newTaskTitle.trim());
    setNewTaskTitle('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      onClose();
    }
  };

  if (!isOpen) return null;

  // 드래그된 위치가 있으면 적용
  const modalStyle = position ? {
    position: 'fixed' as const,
    left: position.x,
    top: position.y,
    margin: 0,
  } : undefined;

  return (
    <div className="project-modal-overlay" onClick={onClose} onKeyDown={handleKeyDown}>
      <div 
        className={`project-modal ${isDragging ? 'dragging' : ''}`} 
        onClick={(e) => e.stopPropagation()}
        style={modalStyle}
      >
        {/* 헤더 - 드래그 핸들 */}
        <div className="modal-header draggable" onMouseDown={handleMouseDown}>
          <h2>{isNew ? 'New Project' : 'Edit Project'}</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        {/* 본문 */}
        <div className="modal-body">
          {/* 제목 */}
          <div className="form-group">
            <label>제목 *</label>
            <input
              ref={titleRef}
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="프로젝트 제목"
              onKeyDown={(e) => e.key === 'Enter' && handleSave()}
            />
          </div>

          {/* 색상 */}
          <div className="form-group">
            <label>색상</label>
            <div className="color-palette">
              {COLORS.map((c) => (
                <button
                  key={c}
                  type="button"
                  className={`color-option ${color === c ? 'selected' : ''}`}
                  style={{ backgroundColor: c }}
                  onClick={() => setColor(c)}
                />
              ))}
            </div>
          </div>

          {/* 메모 */}
          <div className="form-group">
            <label>메모</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="프로젝트 설명"
              rows={2}
            />
          </div>

          {/* 날짜 섹션 */}
          <div className="form-group">
            <label>기간</label>
            <div className="date-inputs">
              <div className="date-field">
                <span className="date-label">시작</span>
                <input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                />
              </div>
              <div className="date-spacer" />
              <div className="date-field">
                <span className="date-label">종료</span>
                <input
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                />
              </div>
            </div>
            {dateError && <span className="error-text">{dateError}</span>}
          </div>

          <div className="form-group">
            <label>마감일</label>
            <input
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
            />
          </div>

          {/* Tasks (기존 프로젝트인 경우) */}
          {!isNew && (
            <div className="form-group tasks-section">
              <label>Tasks ({tasks.length})</label>
              
              {/* 태스크 추가 */}
              {onAddTask && (
                <div className="add-task-row">
                  <input
                    type="text"
                    value={newTaskTitle}
                    onChange={(e) => setNewTaskTitle(e.target.value)}
                    placeholder="새 태스크 추가..."
                    onKeyDown={(e) => e.key === 'Enter' && handleAddTask()}
                  />
                  <button 
                    type="button" 
                    className="add-task-btn"
                    onClick={handleAddTask}
                    disabled={!newTaskTitle.trim()}
                  >
                    +
                  </button>
                </div>
              )}
              
              {/* 태스크 목록 */}
              <div className="tasks-list">
                {tasks.length === 0 ? (
                  <p className="empty-tasks">소속된 태스크가 없습니다</p>
                ) : (
                  tasks.map((task) => (
                    <div 
                      key={task.id} 
                      className={`task-item ${task.status === 'DONE' ? 'done' : ''}`}
                      onClick={() => onTaskClick?.(task)}
                    >
                      <span className="task-status">
                        {task.status === 'DONE' ? '✓' : '○'}
                      </span>
                      <span className="task-title">{task.title}</span>
                      <span className="task-arrow">›</span>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>

        {/* 푸터 */}
        <div className="modal-footer">
          {!isNew && onDelete && (
            <button className="delete-btn" onClick={handleDelete}>
              삭제
            </button>
          )}
          <div className="footer-right">
            <button className="cancel-btn" onClick={onClose}>
              취소
            </button>
            <button 
              className="save-btn" 
              onClick={handleSave}
              disabled={!title.trim() || isSaving}
            >
              {isSaving ? '저장 중...' : (isNew ? '생성' : '저장')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
