// 작업 타임라인 컴포넌트 - 캘린더형 (Week/Month/Year)
import { useState, useMemo } from 'react';
import type { Project, ProjectTask, ProjectTodo } from '../../types/work';
import type { ScheduleEvent } from '../../types';
import './WorkTimeline.css';

// ===== 공통 유틸리티 =====

type ZoomLevel = 'week' | 'month' | 'year';

// 아이템 타입 결정
type ItemDisplayType = 'TIMED' | 'ALLDAY' | 'MULTIDAY' | 'UNSCHEDULED';

interface DisplayItem {
  id: string;
  title: string;
  color: string;
  startAt: Date | null;
  endAt: Date | null;
  isAllDay: boolean;
  displayType: ItemDisplayType;
  original: Project | ProjectTask | ProjectTodo | ScheduleEvent;
  type: 'project' | 'task' | 'todo' | 'schedule';
  isScheduleEvent?: boolean; // 일정에서 추가된 항목인지 (라인만 표시)
}

function getDisplayType(item: { start_at: string | null; end_at: string | null; due_at: string | null; is_all_day: boolean }): ItemDisplayType {
  const hasStart = !!item.start_at;
  const hasEnd = !!item.end_at;
  const hasDue = !!item.due_at;
  
  // 날짜가 전혀 없으면 미정
  if (!hasStart && !hasEnd && !hasDue) return 'UNSCHEDULED';
  
  // 종일 설정이거나 시간이 없으면 종일/다일
  if (item.is_all_day) {
    const start = item.start_at?.split('T')[0];
    const end = (item.end_at || item.due_at)?.split('T')[0];
    if (start && end && start !== end) return 'MULTIDAY';
    return 'ALLDAY';
  }
  
  // 시간이 있는 경우
  if (hasStart && hasEnd) {
    const startDate = item.start_at?.split('T')[0];
    const endDate = item.end_at?.split('T')[0];
    if (startDate !== endDate) return 'MULTIDAY'; // 다일+시간
    return 'TIMED';
  }
  
  // 마감일만 있는 경우
  if (hasDue) return 'ALLDAY';
  
  return 'ALLDAY';
}

function parseDate(dateStr: string | null): Date | null {
  if (!dateStr) return null;
  return new Date(dateStr);
}

function formatTime(date: Date): string {
  return date.toLocaleTimeString('ko-KR', { hour: '2-digit', minute: '2-digit', hour12: false });
}

function formatDateShort(date: Date): string {
  return date.toLocaleDateString('ko-KR', { month: 'short', day: 'numeric' });
}

// 주의 시작일 (월요일) 가져오기
function getWeekStart(date: Date): Date {
  const d = new Date(date);
  const day = d.getDay();
  const diff = d.getDate() - day + (day === 0 ? -6 : 1);
  d.setDate(diff);
  d.setHours(0, 0, 0, 0);
  return d;
}

// 주의 날짜들 가져오기 (월~일)
function getWeekDays(weekStart: Date): Date[] {
  const days: Date[] = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(weekStart);
    d.setDate(d.getDate() + i);
    days.push(d);
  }
  return days;
}

// 같은 날짜인지 비교
function isSameDay(d1: Date, d2: Date): boolean {
  return d1.getFullYear() === d2.getFullYear() &&
         d1.getMonth() === d2.getMonth() &&
         d1.getDate() === d2.getDate();
}

// 날짜가 범위 내에 있는지
function isDateInRange(date: Date, start: Date | null, end: Date | null): boolean {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  
  if (start) {
    const s = new Date(start);
    s.setHours(0, 0, 0, 0);
    if (d < s) return false;
  }
  if (end) {
    const e = new Date(end);
    e.setHours(0, 0, 0, 0);
    if (d > e) return false;
  }
  return true;
}

// ===== Week 뷰 =====
interface WeekViewProps {
  items: DisplayItem[];
  weekStart: Date;
  onItemClick?: (item: DisplayItem) => void;
  onAddClick?: () => void;
  onDateClick?: (date: Date, hour?: number) => void;
}

function WeekView({ items, weekStart, onItemClick, onAddClick, onDateClick }: WeekViewProps) {
  const weekDays = useMemo(() => getWeekDays(weekStart), [weekStart]);
  const hours = Array.from({ length: 24 }, (_, i) => i);
  
  // 아이템 분류
  const { allDayItems, timedItems, unscheduledItems } = useMemo(() => {
    const allDay: DisplayItem[] = [];
    const timed: DisplayItem[] = [];
    const unscheduled: DisplayItem[] = [];
    
    items.forEach(item => {
      if (item.displayType === 'UNSCHEDULED') {
        unscheduled.push(item);
      } else if (item.displayType === 'TIMED') {
        timed.push(item);
      } else {
        allDay.push(item);
      }
    });
    
    return { allDayItems: allDay, timedItems: timed, unscheduledItems: unscheduled };
  }, [items]);
  
  // 특정 날짜에 해당하는 종일 아이템
  const getAllDayItemsForDay = (date: Date) => {
    return allDayItems.filter(item => {
      const start = item.startAt || item.endAt;
      const end = item.endAt || item.startAt;
      if (!start) return false;
      return isDateInRange(date, start, end);
    });
  };
  
  // 특정 날짜의 시간 아이템
  const getTimedItemsForDay = (date: Date) => {
    return timedItems.filter(item => {
      if (!item.startAt) return false;
      return isSameDay(item.startAt, date);
    });
  };
  
  // 아이템 위치 계산 (시간 기준)
  const getItemPosition = (item: DisplayItem) => {
    if (!item.startAt || !item.endAt) return { top: 0, height: 60 };
    
    const startMinutes = item.startAt.getHours() * 60 + item.startAt.getMinutes();
    const endMinutes = item.endAt.getHours() * 60 + item.endAt.getMinutes();
    const duration = Math.max(endMinutes - startMinutes, 30);
    
    return {
      top: (startMinutes / 60) * 60, // 60px per hour
      height: (duration / 60) * 60,
    };
  };
  
  return (
    <div className="week-view">
      {/* 상단 날짜 헤더 */}
      <div className="week-header">
        <div className="time-column-header"></div>
        {weekDays.map((day, i) => {
          const isToday = isSameDay(day, new Date());
          return (
            <div key={i} className={`day-header ${isToday ? 'today' : ''}`}>
              <span className="day-name">{['일', '월', '화', '수', '목', '금', '토'][day.getDay()]}</span>
              <span className="day-date">{day.getDate()}</span>
            </div>
          );
        })}
      </div>
      
      {/* All-day 레인 */}
      <div className="allday-lane">
        <div className="time-column-label">종일</div>
        {weekDays.map((day, i) => {
          const dayItems = getAllDayItemsForDay(day);
          return (
            <div 
              key={i} 
              className="allday-cell clickable"
              onClick={(e) => {
                // 아이템 클릭이 아닐 때만 추가
                if ((e.target as HTMLElement).classList.contains('allday-cell')) {
                  onDateClick?.(day);
                }
              }}
            >
              {dayItems.slice(0, 3).map(item => {
                // 다일 바인지 확인
                const isMultiDay = item.displayType === 'MULTIDAY' || item.displayType === 'ALLDAY';
                const startDate = item.startAt || item.endAt;
                const endDate = item.endAt || item.startAt;
                const isStart = startDate && isSameDay(startDate, day);
                const isEnd = endDate && isSameDay(endDate, day);
                const isMiddle = isMultiDay && !isStart && !isEnd;
                
                // 클래스 결정: start (왼쪽 라운드), end (오른쪽 라운드), middle (라운드 없음)
                let positionClass = '';
                if (isMultiDay && startDate && endDate && !isSameDay(startDate, endDate)) {
                  if (isStart && isEnd) positionClass = ''; // 하루짜리
                  else if (isStart) positionClass = 'bar-start';
                  else if (isEnd) positionClass = 'bar-end';
                  else if (isMiddle) positionClass = 'bar-middle';
                }
                
                return (
                  <div
                    key={item.id}
                    className={`allday-item ${positionClass} ${item.isScheduleEvent ? 'schedule-outline' : ''}`}
                    style={{ 
                      backgroundColor: item.isScheduleEvent ? 'transparent' : item.color,
                      borderColor: item.color,
                    }}
                    onClick={() => onItemClick?.(item)}
                    title={item.title}
                  >
                    {isStart && (
                      <span className="item-title">{item.title}</span>
                    )}
                  </div>
                );
              })}
              {dayItems.length > 3 && (
                <div className="more-items">+{dayItems.length - 3}</div>
              )}
            </div>
          );
        })}
      </div>
      
      {/* 시간 그리드 */}
      <div className="time-grid-container">
        <div className="time-grid">
          {/* 시간 레이블 */}
          <div className="time-column">
            {hours.map(hour => (
              <div key={hour} className="time-label">
                {String(hour).padStart(2, '0')}:00
              </div>
            ))}
          </div>
          
          {/* 날짜별 컬럼 */}
          {weekDays.map((day, dayIndex) => {
            const dayTimedItems = getTimedItemsForDay(day);
            const isToday = isSameDay(day, new Date());
            
            return (
              <div key={dayIndex} className={`day-column ${isToday ? 'today' : ''}`}>
                {/* 시간 라인 (클릭하여 추가) */}
                {hours.map(hour => (
                  <div 
                    key={hour} 
                    className="hour-line clickable" 
                    onClick={() => {
                      const d = new Date(day);
                      d.setHours(hour, 0, 0, 0);
                      onDateClick?.(d, hour);
                    }}
                  />
                ))}
                
                {/* 시간 블록 이벤트 */}
                {dayTimedItems.map((item, idx) => {
                  const { top, height } = getItemPosition(item);
                  return (
                    <div
                      key={item.id}
                      className={`timed-item ${item.isScheduleEvent ? 'schedule-outline' : ''}`}
                      style={{
                        top: `${top}px`,
                        height: `${height}px`,
                        backgroundColor: item.isScheduleEvent ? 'transparent' : item.color,
                        borderColor: item.color,
                        left: `${idx * 10}%`,
                        width: `${90 - idx * 10}%`,
                      }}
                      onClick={() => onItemClick?.(item)}
                      title={item.title}
                    >
                      <span className="item-time">
                        {item.startAt && formatTime(item.startAt)}
                      </span>
                      <span className="item-title">{item.title}</span>
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>
      </div>
      
      {/* 미정 리스트 */}
      {unscheduledItems.length > 0 && (
        <div className="unscheduled-section">
          <div className="unscheduled-header">
            <span>📋 미정 (날짜 없음)</span>
          </div>
          <div className="unscheduled-list">
            {unscheduledItems.map(item => (
              <div
                key={item.id}
                className="unscheduled-item"
                style={{ borderLeftColor: item.color }}
                onClick={() => onItemClick?.(item)}
              >
                {item.title}
              </div>
            ))}
          </div>
        </div>
      )}
      
      {/* 추가 버튼 */}
      {onAddClick && (
        <button className="timeline-add-btn" onClick={onAddClick}>
          + 추가
        </button>
      )}
    </div>
  );
}

// ===== Month 뷰 =====
interface MonthViewProps {
  items: DisplayItem[];
  year: number;
  month: number;
  onItemClick?: (item: DisplayItem) => void;
  onAddClick?: () => void;
  onDateClick?: (date: Date) => void;
}

function MonthView({ items, year, month, onItemClick, onAddClick, onDateClick }: MonthViewProps) {
  // 월의 달력 데이터 생성
  const calendarData = useMemo(() => {
    const firstDay = new Date(year, month - 1, 1);
    const lastDay = new Date(year, month, 0);
    const startDayOfWeek = firstDay.getDay(); // 0 = Sunday
    const totalDays = lastDay.getDate();
    
    const weeks: (Date | null)[][] = [];
    let currentWeek: (Date | null)[] = [];
    
    // 첫 주의 빈 칸
    for (let i = 0; i < startDayOfWeek; i++) {
      currentWeek.push(null);
    }
    
    // 날짜 채우기
    for (let day = 1; day <= totalDays; day++) {
      currentWeek.push(new Date(year, month - 1, day));
      if (currentWeek.length === 7) {
        weeks.push(currentWeek);
        currentWeek = [];
      }
    }
    
    // 마지막 주의 빈 칸
    if (currentWeek.length > 0) {
      while (currentWeek.length < 7) {
        currentWeek.push(null);
      }
      weeks.push(currentWeek);
    }
    
    return weeks;
  }, [year, month]);
  
  // 특정 날짜에 해당하는 아이템
  const getItemsForDay = (date: Date) => {
    return items.filter(item => {
      if (item.displayType === 'UNSCHEDULED') return false;
      
      const start = item.startAt;
      const end = item.endAt || item.startAt;
      
      if (!start) return false;
      return isDateInRange(date, start, end);
    });
  };
  
  return (
    <div className="month-view">
      {/* 요일 헤더 */}
      <div className="month-header">
        {['일', '월', '화', '수', '목', '금', '토'].map(day => (
          <div key={day} className="weekday-header">{day}</div>
        ))}
      </div>
      
      {/* 달력 그리드 */}
      <div className="month-grid">
        {calendarData.map((week, weekIndex) => (
          <div key={weekIndex} className="week-row">
            {week.map((date, dayIndex) => {
              if (!date) {
                return <div key={dayIndex} className="day-cell empty" />;
              }
              
              const isToday = isSameDay(date, new Date());
              const dayItems = getItemsForDay(date);
              
              return (
                <div 
                  key={dayIndex} 
                  className={`day-cell clickable ${isToday ? 'today' : ''}`}
                  onClick={(e) => {
                    if ((e.target as HTMLElement).classList.contains('day-cell') || 
                        (e.target as HTMLElement).classList.contains('day-number') ||
                        (e.target as HTMLElement).classList.contains('day-items')) {
                      onDateClick?.(date);
                    }
                  }}
                >
                  <div className="day-number">{date.getDate()}</div>
                  <div className="day-items">
                    {dayItems.slice(0, 3).map(item => {
                      const startDate = item.startAt || item.endAt;
                      const endDate = item.endAt || item.startAt;
                      const isStart = startDate && isSameDay(startDate, date);
                      const isEnd = endDate && isSameDay(endDate, date);
                      const isMultiDay = startDate && endDate && !isSameDay(startDate, endDate);
                      
                      // 클래스 결정
                      let positionClass = '';
                      if (isMultiDay) {
                        if (isStart) positionClass = 'bar-start';
                        else if (isEnd) positionClass = 'bar-end';
                        else positionClass = 'bar-middle';
                      }
                      
                      return (
                        <div
                          key={item.id}
                          className={`month-item ${positionClass} ${item.isScheduleEvent ? 'schedule-outline' : ''}`}
                          style={{ 
                            backgroundColor: item.isScheduleEvent ? 'transparent' : item.color,
                            borderColor: item.color,
                          }}
                          onClick={() => onItemClick?.(item)}
                          title={item.title}
                        >
                          {isStart ? item.title : ''}
                        </div>
                      );
                    })}
                    {dayItems.length > 3 && (
                      <div className="more-items">+{dayItems.length - 3}</div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        ))}
      </div>
      
      {/* 추가 버튼 */}
      {onAddClick && (
        <button className="timeline-add-btn" onClick={onAddClick}>
          + 추가
        </button>
      )}
    </div>
  );
}

// ===== Year 뷰 =====
interface YearViewProps {
  items: DisplayItem[];
  year: number;
  onMonthClick: (month: number) => void;
  onAddClick?: () => void;
  onItemClick?: (item: DisplayItem) => void;
}

function YearView({ items, year, onMonthClick, onAddClick, onItemClick }: YearViewProps) {
  const months = [
    '1월', '2월', '3월', '4월', '5월', '6월',
    '7월', '8월', '9월', '10월', '11월', '12월'
  ];
  
  // 월별 아이템 그룹
  const monthItems = useMemo(() => {
    const groups: DisplayItem[][] = Array.from({ length: 12 }, () => []);
    
    items.forEach(item => {
      if (item.displayType === 'UNSCHEDULED') return;
      
      const start = item.startAt;
      const end = item.endAt || item.startAt;
      
      if (!start) return;
      
      const startMonth = start.getMonth();
      const startYear = start.getFullYear();
      const endYear = end ? end.getFullYear() : startYear;
      
      // 시작 월에만 추가 (바로 표시)
      if (startYear === year && !groups[startMonth].find(i => i.id === item.id)) {
        groups[startMonth].push(item);
      } else if (startYear < year && endYear >= year) {
        // 전년도에서 시작해서 올해까지 이어지는 경우, 1월에 추가
        if (!groups[0].find(i => i.id === item.id)) {
          groups[0].push(item);
        }
      }
    });
    
    return groups;
  }, [items, year]);
  
  return (
    <div className="year-view">
      <div className="year-title">{year}년</div>
      
      <div className="year-months-container">
        {months.map((monthName, index) => {
          const monthItemList = monthItems[index];
          const isCurrentMonth = new Date().getFullYear() === year && new Date().getMonth() === index;
          
          return (
            <div
              key={index}
              className={`year-month-row ${isCurrentMonth ? 'current' : ''}`}
            >
              <div 
                className="year-month-header"
                onClick={() => onMonthClick(index + 1)}
              >
                <span className="month-name">{monthName}</span>
                <span className="item-count">{monthItemList.length > 0 ? `(${monthItemList.length})` : ''}</span>
              </div>
              <div className="year-month-items">
                {monthItemList.slice(0, 5).map(item => (
                  <div
                    key={item.id}
                    className="year-item-bar"
                    style={{ backgroundColor: item.color }}
                    onClick={(e) => {
                      e.stopPropagation();
                      onItemClick?.(item);
                    }}
                    title={item.title}
                  >
                    {item.title}
                  </div>
                ))}
                {monthItemList.length > 5 && (
                  <div className="more-items" onClick={() => onMonthClick(index + 1)}>
                    +{monthItemList.length - 5}개 더보기
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
      
      {/* 추가 버튼 */}
      {onAddClick && (
        <button className="timeline-add-btn" onClick={onAddClick}>
          + 추가
        </button>
      )}
    </div>
  );
}

// ===== 메인 컴포넌트 (통합 타임라인) =====
interface CalendarTimelineProps {
  items: DisplayItem[];
  zoom: ZoomLevel;
  onZoomChange: (zoom: ZoomLevel) => void;
  onItemClick?: (item: DisplayItem) => void;
  onAddClick?: () => void;
  onDateClick?: (date: Date, hour?: number) => void;
}

function CalendarTimeline({ items, zoom, onZoomChange, onItemClick, onAddClick, onDateClick }: CalendarTimelineProps) {
  const [currentDate, setCurrentDate] = useState(() => new Date());
  
  // 네비게이션
  const handlePrev = () => {
    const d = new Date(currentDate);
    if (zoom === 'week') {
      d.setDate(d.getDate() - 7);
    } else if (zoom === 'month') {
      d.setMonth(d.getMonth() - 1);
    } else {
      d.setFullYear(d.getFullYear() - 1);
    }
    setCurrentDate(d);
  };
  
  const handleNext = () => {
    const d = new Date(currentDate);
    if (zoom === 'week') {
      d.setDate(d.getDate() + 7);
    } else if (zoom === 'month') {
      d.setMonth(d.getMonth() + 1);
    } else {
      d.setFullYear(d.getFullYear() + 1);
    }
    setCurrentDate(d);
  };
  
  const handleToday = () => {
    setCurrentDate(new Date());
  };
  
  // 년도 뷰에서 월 클릭 시
  const handleMonthClick = (month: number) => {
    const d = new Date(currentDate);
    d.setMonth(month - 1);
    setCurrentDate(d);
    onZoomChange('month');
  };
  
  // 날짜 표시 텍스트
  const getDateDisplay = () => {
    if (zoom === 'week') {
      const weekStart = getWeekStart(currentDate);
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekEnd.getDate() + 6);
      return `${formatDateShort(weekStart)} - ${formatDateShort(weekEnd)}`;
    } else if (zoom === 'month') {
      return `${currentDate.getFullYear()}년 ${currentDate.getMonth() + 1}월`;
    } else {
      return `${currentDate.getFullYear()}년`;
    }
  };
  
  return (
    <div className="calendar-timeline">
      {/* 툴바 */}
      <div className="timeline-toolbar">
        <div className="nav-controls">
          <button className="nav-btn" onClick={handlePrev}>◀</button>
          <span className="date-display">{getDateDisplay()}</span>
          <button className="nav-btn" onClick={handleNext}>▶</button>
          <button className="today-btn" onClick={handleToday}>오늘</button>
        </div>
        
        <div className="zoom-controls">
          <button 
            className={`zoom-btn ${zoom === 'week' ? 'active' : ''}`}
            onClick={() => onZoomChange('week')}
          >
            Week
          </button>
          <button 
            className={`zoom-btn ${zoom === 'month' ? 'active' : ''}`}
            onClick={() => onZoomChange('month')}
          >
            Month
          </button>
          <button 
            className={`zoom-btn ${zoom === 'year' ? 'active' : ''}`}
            onClick={() => onZoomChange('year')}
          >
            Year
          </button>
        </div>
      </div>
      
      {/* 뷰 렌더링 */}
      <div className="timeline-content">
        {zoom === 'week' && (
          <WeekView
            items={items}
            weekStart={getWeekStart(currentDate)}
            onItemClick={onItemClick}
            onAddClick={onAddClick}
            onDateClick={onDateClick}
          />
        )}
        {zoom === 'month' && (
          <MonthView
            items={items}
            year={currentDate.getFullYear()}
            month={currentDate.getMonth() + 1}
            onItemClick={onItemClick}
            onAddClick={onAddClick}
            onDateClick={onDateClick}
          />
        )}
        {zoom === 'year' && (
          <YearView
            items={items}
            year={currentDate.getFullYear()}
            onMonthClick={handleMonthClick}
            onAddClick={onAddClick}
            onItemClick={onItemClick}
          />
        )}
      </div>
    </div>
  );
}

// ===== 프로젝트 타임라인 =====
interface ProjectsTimelineProps {
  projects: Project[];
  showCompleted: boolean;
  onProjectClick?: (project: Project) => void;
  onAddClick?: () => void;
  onDateClick?: (date: Date, hour?: number) => void;
}

export function ProjectsTimeline({ projects, showCompleted, onProjectClick, onAddClick, onDateClick }: ProjectsTimelineProps) {
  const [zoom, setZoom] = useState<ZoomLevel>('month');
  
  // 프로젝트를 DisplayItem으로 변환
  const items: DisplayItem[] = useMemo(() => {
    const filtered = showCompleted ? projects : projects.filter(p => p.status === 'ACTIVE');
    
    return filtered.map(p => ({
      id: p.id,
      title: p.title,
      color: p.color,
      startAt: parseDate(p.start_at),
      endAt: parseDate(p.end_at || p.due_at),
      isAllDay: p.is_all_day,
      displayType: getDisplayType(p),
      original: p,
      type: 'project' as const,
    }));
  }, [projects, showCompleted]);
  
  const handleItemClick = (item: DisplayItem) => {
    if (item.type === 'project') {
      onProjectClick?.(item.original as Project);
    }
  };
  
  return (
    <CalendarTimeline
      items={items}
      zoom={zoom}
      onZoomChange={setZoom}
      onItemClick={handleItemClick}
      onAddClick={onAddClick}
      onDateClick={onDateClick}
    />
  );
}

// ===== 태스크 타임라인 =====
interface TasksTimelineProps {
  tasks: ProjectTask[];
  projects: Project[];
  scheduleEvents?: ScheduleEvent[]; // 일정 이벤트 추가
  showCompleted: boolean;
  onTaskClick?: (task: ProjectTask) => void;
  onScheduleEventClick?: (event: ScheduleEvent) => void; // 일정 클릭 핸들러
  onAddClick?: () => void;
  onDateClick?: (date: Date, hour?: number) => void;
}

export function TasksTimeline({ tasks, projects, scheduleEvents = [], showCompleted, onTaskClick, onScheduleEventClick, onAddClick, onDateClick }: TasksTimelineProps) {
  const [zoom, setZoom] = useState<ZoomLevel>('week');
  
  // 프로젝트 색상 맵
  const projectColors = useMemo(() => {
    const map: Record<string, string> = {};
    projects.forEach(p => {
      map[p.id] = p.color;
    });
    return map;
  }, [projects]);
  
  // 태스크를 DisplayItem으로 변환
  const taskItems: DisplayItem[] = useMemo(() => {
    const filtered = showCompleted ? tasks : tasks.filter(t => t.status === 'ACTIVE');
    
    return filtered.map(t => ({
      id: t.id,
      title: t.title,
      color: t.projectId ? (projectColors[t.projectId] || '#6b7280') : '#6b7280',
      startAt: parseDate(t.start_at),
      endAt: parseDate(t.end_at || t.due_at),
      isAllDay: t.is_all_day,
      displayType: getDisplayType(t),
      original: t,
      type: 'task' as const,
      isScheduleEvent: false,
    }));
  }, [tasks, showCompleted, projectColors]);

  // 일정 이벤트를 DisplayItem으로 변환
  const scheduleItems: DisplayItem[] = useMemo(() => {
    const filtered = showCompleted ? scheduleEvents : scheduleEvents.filter(e => e.status !== 'cancelled');
    
    return filtered.map(e => {
      // 시작/종료 날짜+시간 파싱
      const startDateTime = new Date(`${e.date}T${e.start}`);
      const endDate = e.endDate || e.date;
      const endDateTime = new Date(`${endDate}T${e.end}`);
      
      const isAllDay = e.isAllDay || false;
      const isMultiDay = e.endDate && e.endDate !== e.date;
      
      return {
        id: `schedule-${e.id}`,
        title: e.title,
        color: e.color,
        startAt: startDateTime,
        endAt: endDateTime,
        isAllDay,
        displayType: isAllDay ? (isMultiDay ? 'MULTIDAY' : 'ALLDAY') : 'TIMED' as ItemDisplayType,
        original: e,
        type: 'schedule' as const,
        isScheduleEvent: true, // 라인만 표시하기 위한 플래그
      };
    });
  }, [scheduleEvents, showCompleted]);

  // 합친 아이템
  const items = useMemo(() => [...taskItems, ...scheduleItems], [taskItems, scheduleItems]);
  
  const handleItemClick = (item: DisplayItem) => {
    if (item.type === 'task') {
      onTaskClick?.(item.original as ProjectTask);
    } else if (item.type === 'schedule') {
      onScheduleEventClick?.(item.original as ScheduleEvent);
    }
  };
  
  return (
    <CalendarTimeline
      items={items}
      zoom={zoom}
      onZoomChange={setZoom}
      onItemClick={handleItemClick}
      onAddClick={onAddClick}
      onDateClick={onDateClick}
    />
  );
}

// ===== To do 타임라인 =====
interface TodosTimelineProps {
  todos: ProjectTodo[];
  doneTodos: ProjectTodo[];
  tasks: ProjectTask[];
  projects: Project[];
  showCompleted: boolean;
  onTodoClick?: (todo: ProjectTodo) => void;
  onAddClick?: () => void;
  onDateClick?: (date: Date, hour?: number) => void;
}

export function TodosTimeline({ todos, doneTodos, tasks, projects, showCompleted, onTodoClick, onAddClick, onDateClick }: TodosTimelineProps) {
  const [zoom, setZoom] = useState<ZoomLevel>('week');
  
  // 태스크별 프로젝트 색상 맵
  const taskColors = useMemo(() => {
    const projectColorMap: Record<string, string> = {};
    projects.forEach(p => {
      projectColorMap[p.id] = p.color;
    });
    
    const map: Record<string, string> = {};
    tasks.forEach(t => {
      map[t.id] = t.projectId ? (projectColorMap[t.projectId] || '#6b7280') : '#6b7280';
    });
    return map;
  }, [tasks, projects]);
  
  // To do를 DisplayItem으로 변환
  const items: DisplayItem[] = useMemo(() => {
    const allTodos = showCompleted ? [...todos, ...doneTodos] : todos;
    
    return allTodos.map(t => ({
      id: t.id,
      title: t.content,
      color: t.taskId ? (taskColors[t.taskId] || '#6b7280') : '#6b7280',
      startAt: parseDate(t.start_at),
      endAt: parseDate(t.end_at || t.due_at),
      isAllDay: t.is_all_day,
      displayType: getDisplayType(t),
      original: t,
      type: 'todo' as const,
    }));
  }, [todos, doneTodos, showCompleted, taskColors]);
  
  const handleItemClick = (item: DisplayItem) => {
    if (item.type === 'todo') {
      onTodoClick?.(item.original as ProjectTodo);
    }
  };
  
  return (
    <CalendarTimeline
      items={items}
      zoom={zoom}
      onZoomChange={setZoom}
      onItemClick={handleItemClick}
      onAddClick={onAddClick}
      onDateClick={onDateClick}
    />
  );
}
